def _collect_ledger_files(
    files: list[Path],
    *,
    dataset: str,
    columns: list[str] | None,
) -> pl.DataFrame:
    """Union a set of parquet part files into one frame, transparently dropping
    the internal _ledger_month partition column so the returned frame is
    schema-identical to the legacy monolithic layout. For a bucketed ledger this
    unions the legacy part.parquet (if any) with the new _ledger_month=* buckets;
    a cross-bucket unique() guarantees a key present in BOTH the legacy file and
    a migrated bucket (the migration window) is never double-counted on read."""
    if not files:
        return pl.DataFrame()
    file_paths = [str(file) for file in files]
    try:
        lf = pl.scan_parquet(file_paths)
        names = lf.collect_schema().names()
        if _LEDGER_MONTH_COL in names:
            lf = lf.drop(_LEDGER_MONTH_COL)
            names = [n for n in names if n != _LEDGER_MONTH_COL]
        if columns is not None:
            lf = lf.select([col for col in columns if col in names])
        out = lf.collect()
    except pl.exceptions.SchemaError:
        frames = [pl.read_parquet(file) for file in file_paths]
        out = pl.concat(frames, how="diagonal_relaxed") if frames else pl.DataFrame()
        if _LEDGER_MONTH_COL in out.columns:
            out = out.drop(_LEDGER_MONTH_COL)
        if columns is not None and not out.is_empty():
            out = out.select([col for col in columns if col in out.columns])
    # Cross-bucket dedup: per-part-file dedup in _write_part does not span the
    # legacy monolith + a migrated bucket during the migration window. Coalesce
    # on the dataset key, preferring the freshest updated_at_ms when present
    # (mirrors _write_part recency), so a key in both is never doubled.
    keys = [c for c in DATASET_KEYS.get(dataset, ()) if c in out.columns]
    if keys and not out.is_empty():
        if "updated_at_ms" in out.columns:
            out = out.sort("updated_at_ms", nulls_last=False)
        out = out.unique(subset=keys, keep="last")
    return out


def read_ledger_window(
    data_root: str | Path,
    dataset: str,
    *,
    months_back: int = 3,
) -> pl.DataFrame:
    """Windowed read of a month-bucketed ledger: only the most-recent
    ``months_back`` month buckets plus the legacy monolith / _ledger_month=0
    tail. quality-dup-5: ws_risk's per-reconcile read no longer scales with the
    daemon's whole-history ledger -- it only needs OPEN trades and
    recently-touched orders, and an open trade older than the window is still
    served by the always-included legacy tail until migration drains it. Falls
    back to the full read for a non-bucketed dataset (no _ledger_month dirs)."""
    path = dataset_path(data_root, dataset)
    if not path.exists():
        return pl.DataFrame()
    with exclusive_file_lock(dataset_lock_path(data_root, dataset), stale_seconds=21_600, poll_seconds=0.01):
        bucket_dirs = _recent_ledger_month_dirs(path, months_back)
        if not bucket_dirs:
            files = sorted(path.glob("**/*.parquet"))
        else:
            legacy = sorted(path.glob("part.parquet"))
            files = legacy + sorted(
                f for d in bucket_dirs for f in d.glob("**/*.parquet")
            )
        return _collect_ledger_files(files, dataset=dataset, columns=None)

